"""Workflow-aware quest and child machine state I/O."""

from __future__ import annotations

from pathlib import Path
from typing import Mapping

from .. import quest_fs
from ..quest_service import FatalInvariantError
from ..quest_types import (
    QuestMeta,
    RecursiveSnapshot,
    StateMachineState,
    slice_index_from_dirname,
)
from ..workflow_config import WorkflowCollection, WorkflowDefinition, WorkflowState

_IDENTITY_TAGS = frozenset({"quest_type", "quest_number", "quest_slug"})
_RESERVED_TOP_LEVEL_PERSISTED = frozenset({"ExperimentComplete"})
_NORMALIZED_STATE_HEADING = "# State"


def _path_matches_collection_pattern(rel_path: str, pattern: str) -> bool:
    pattern_parts = pattern.split("/")
    path_parts = rel_path.split("/")
    if len(pattern_parts) != len(path_parts):
        return False
    for pattern_part, path_part in zip(pattern_parts, path_parts):
        if pattern_part == "*":
            continue
        if pattern_part != path_part:
            return False
    return True


class WorkflowStateIo:
    """``StateIo`` that reads and writes state via workflow machine definitions."""

    def __init__(
        self,
        repo_path: Path,
        quest_dir: Path,
        meta: QuestMeta,
        workflow: WorkflowDefinition,
    ) -> None:
        self.repo_path = repo_path.resolve()
        self.quest_dir = quest_dir.resolve()
        self.meta = meta
        self.workflow = workflow

    def ReadStateMachineState(self, state_machine_dir: Path) -> StateMachineState:
        machine_dir = state_machine_dir.resolve()
        machine_key = self._machine_key_for_dir(machine_dir)
        if machine_key == self.workflow.entry_machine:
            return self._read_quest(machine_key)
        return self._read_child(machine_key, machine_dir)

    def WriteStateMachineState(
        self, state_machine_dir: Path, state: StateMachineState
    ) -> None:
        machine_dir = state_machine_dir.resolve()
        machine_key = self._machine_key_for_dir(machine_dir)
        if machine_key == self.workflow.entry_machine:
            self._write_quest(machine_key, state)
        else:
            self._write_child(machine_key, machine_dir, state)

    def logical_state_for_persisted(
        self, machine_key: str, persisted_state: str
    ) -> str:
        if (
            machine_key == self.workflow.entry_machine
            and persisted_state in _RESERVED_TOP_LEVEL_PERSISTED
        ):
            return persisted_state
        machine = self.workflow.get_machine(machine_key)
        for state_def in machine.states.values():
            if state_def.persisted_as == persisted_state:
                return state_def.name
        if persisted_state in machine.states:
            return persisted_state
        raise FatalInvariantError(
            f"Persisted state {persisted_state!r} is not declared for machine "
            f"{machine_key!r}"
        )

    def persisted_state_for_logical(self, machine_key: str, logical_state: str) -> str:
        if (
            machine_key == self.workflow.entry_machine
            and logical_state in _RESERVED_TOP_LEVEL_PERSISTED
        ):
            return logical_state
        machine = self.workflow.get_machine(machine_key)
        state_def = machine.states.get(logical_state)
        if state_def is None:
            raise FatalInvariantError(
                f"Logical state {logical_state!r} is not declared for machine "
                f"{machine_key!r}"
            )
        if state_def.persisted_as is not None:
            return state_def.persisted_as
        return logical_state

    def machine_name_for_instance(self, machine_key: str, machine_dir: Path) -> str:
        machine = self.workflow.get_machine(machine_key)
        if machine_dir.resolve() == self.quest_dir:
            return machine.machine
        return f"{machine.machine}_{machine_dir.name}"

    def machine_path_for_instance(self, machine_dir: Path) -> str:
        return machine_dir.resolve().relative_to(self.repo_path).as_posix()

    def _machine_key_for_dir(self, machine_dir: Path) -> str:
        if machine_dir.resolve() == self.quest_dir:
            return self.workflow.entry_machine
        collection = self._collection_for_dir(machine_dir)
        if collection is not None:
            return collection.machine
        raise FatalInvariantError(
            f"Directory {machine_dir} does not match any workflow collection"
        )

    def _collection_for_dir(self, machine_dir: Path) -> WorkflowCollection | None:
        if machine_dir.resolve() == self.quest_dir:
            return None
        rel = machine_dir.resolve().relative_to(self.quest_dir).as_posix()
        for collection in self.workflow.collections.values():
            if _path_matches_collection_pattern(rel, collection.path):
                return collection
        return None

    def _read_quest(self, machine_key: str) -> StateMachineState:
        path = self.quest_dir / "state.md"
        text = path.read_text(encoding="utf-8")
        first: str | None = None
        for ln in text.splitlines():
            s = ln.strip()
            if not s:
                continue
            first = s
            break
        if first == _NORMALIZED_STATE_HEADING:
            sm = quest_fs.parse_normalized_state_md_text(
                text,
                require_global_step=False,
                label=f"normalized quest state file {path}",
            )
            logical = self.logical_state_for_persisted(machine_key, sm.state)
            g = sm.global_step if sm.global_step is not None else 0
            return StateMachineState(
                machine_name=sm.machine_name,
                machine_path=sm.machine_path,
                state=logical,
                global_step=g,
                tags=dict(sm.tags),
                updated_at=sm.updated_at,
            )
        info = quest_fs.read_quest_state(self.quest_dir)
        logical = self.logical_state_for_persisted(machine_key, info.state.value)
        rel = self.quest_dir.relative_to(self.repo_path).as_posix()
        tags: dict[str, str] = {}
        if info.active_slice:
            tags["active_slice"] = info.active_slice
        return StateMachineState(
            machine_name=self.workflow.get_machine(machine_key).machine,
            machine_path=rel,
            state=logical,
            global_step=info.global_step if info.global_step is not None else 0,
            tags=tags,
            updated_at=info.updated_at,
        )

    def _read_child(self, machine_key: str, machine_dir: Path) -> StateMachineState:
        persisted, updated_at = quest_fs.read_slice_persisted_state(machine_dir)
        logical = self.logical_state_for_persisted(machine_key, persisted)
        return StateMachineState(
            machine_name=self.machine_name_for_instance(machine_key, machine_dir),
            machine_path=self.machine_path_for_instance(machine_dir),
            state=logical,
            global_step=None,
            tags={},
            updated_at=updated_at,
        )

    def _write_quest(self, machine_key: str, sm: StateMachineState) -> None:
        persisted = self.persisted_state_for_logical(machine_key, sm.state)
        gs = sm.global_step if sm.global_step is not None else 0
        tags: dict[str, str] = {
            "quest_type": self.meta.quest_type,
            "quest_number": str(self.meta.quest_number),
            "quest_slug": self.meta.quest_slug,
        }
        for key, value in sm.tags.items():
            if key not in _IDENTITY_TAGS:
                tags[key] = value
        rel = self.quest_dir.relative_to(self.repo_path).as_posix()
        out = StateMachineState(
            machine_name=self.workflow.get_machine(machine_key).machine,
            machine_path=rel,
            state=persisted,
            global_step=gs,
            tags=tags,
            updated_at=sm.updated_at,
        )
        quest_fs.write_normalized_machine_state(self.quest_dir, out)

    def _write_child(
        self, machine_key: str, machine_dir: Path, sm: StateMachineState
    ) -> None:
        persisted = self.persisted_state_for_logical(machine_key, sm.state)
        quest_fs.write_slice_persisted_state(
            machine_dir,
            persisted_state=persisted,
            updated_at=sm.updated_at,
        )


def build_workflow_step_snapshot(
    *,
    workflow_io: WorkflowStateIo,
    machine_key: str,
    machine_dir: Path,
    workflow_state: WorkflowState,
    state_before: str,
    state_after: str,
    tags: Mapping[str, str],
    child: RecursiveSnapshot | None = None,
) -> RecursiveSnapshot:
    """Build a recursive snapshot from execution-local workflow step data."""
    node_name = (
        workflow_state.node_name
        if workflow_state.node_name is not None
        else workflow_state.name
    )
    return RecursiveSnapshot(
        machine_path=workflow_io.machine_path_for_instance(machine_dir),
        machine_name=workflow_io.machine_name_for_instance(machine_key, machine_dir),
        node_name=node_name,
        state_before=state_before,
        state_after=state_after,
        tags=dict(tags),
        child=child,
    )

"""Shared quest/slice transition predicates for v2 runner and manual advance."""

from __future__ import annotations

from pathlib import Path

from .. import quest_fs
from ..quest_runner import (
    all_required_slice_plan_files_exist,
    current_project_rel_for_quest,
    docs_updated_for_quest,
    implementer_done_signal,
    implementation_review_done_signal,
    physical_plan_review_done_signal,
    quest_has_open_physicalplan_issues,
    slice_has_open_polishing_issues,
)
from ..quest_types import QuestMeta, SliceState


class AdvanceValidationError(Exception):
    """Manual advance blocked by unmet predicates; state must not change."""

    def __init__(self, message: str, *, reason: str) -> None:
        self.message = message
        self.reason = reason
        super().__init__(message)


def physical_planning_next_state(quest_dir: Path) -> str:
    slice_dirs = quest_fs.list_slice_dirs(quest_dir)
    if slice_dirs and all_required_slice_plan_files_exist(quest_dir):
        return "ReviewPhysicalPlan"
    raise AdvanceValidationError(
        "Physical planning is incomplete: slice directories and required "
        "physicalplan/state files are missing.",
        reason="incomplete_physical_plan",
    )


def review_physical_plan_next_state(quest_dir: Path) -> str:
    if quest_has_open_physicalplan_issues(quest_dir):
        return "PhysicalPlanning"
    if physical_plan_review_done_signal(quest_dir):
        return "PrepareNextSlice"
    raise AdvanceValidationError(
        "Physical plan review is incomplete: resolve open issues and create "
        "`physicalplan_accepted.md` before advancing.",
        reason="physical_plan_review_incomplete",
    )


def prepare_next_slice_transition(quest_dir: Path) -> tuple[str, dict[str, str]]:
    dirs = quest_fs.list_slice_dirs(quest_dir)
    unfinished = [
        d
        for d in dirs
        if quest_fs.read_slice_state(d).state != SliceState.Done
    ]
    if not unfinished:
        return "QuestDocumenting", {}
    top = quest_fs.read_quest_state(quest_dir)
    cur = top.active_slice
    order = [d.name for d in dirs]
    if not cur:
        return "ExecuteSlice", {"active_slice": unfinished[0].name}
    try:
        i = order.index(cur)
    except ValueError:
        return "ExecuteSlice", {"active_slice": unfinished[0].name}
    for d in unfinished:
        if order.index(d.name) > i:
            return "ExecuteSlice", {"active_slice": d.name}
    return "QuestDocumenting", {}


def slice_implementing_next_state(slice_dir: Path) -> str:
    if implementer_done_signal(slice_dir, slice_dir, ""):
        return "PolishingReview"
    raise AdvanceValidationError(
        "Slice implementation is incomplete: create `implementation_done.md` "
        "before advancing.",
        reason="missing_implementation_done",
    )


def slice_polishing_review_next_state(slice_dir: Path) -> str:
    if slice_has_open_polishing_issues(slice_dir):
        return "PolishingFix"
    if implementation_review_done_signal(slice_dir):
        return "Completed"
    raise AdvanceValidationError(
        "Slice polishing review is incomplete: resolve open issues and create "
        "`implementation_accepted.md` before advancing.",
        reason="polishing_review_incomplete",
    )


def quest_documenting_next_state(
    *,
    repo_path: Path,
    quest_dir: Path,
    meta: QuestMeta,
    documenter_base_ref: str,
) -> str:
    quest_rel = quest_dir.resolve().relative_to(repo_path.resolve()).as_posix()
    project_rel = current_project_rel_for_quest(meta, quest_rel)
    docs_rel = f"{project_rel}/docs" if project_rel else "docs"
    if documenter_base_ref and docs_updated_for_quest(
        repo_path, documenter_base_ref, docs_rel
    ):
        return "Completed"
    raise AdvanceValidationError(
        "Quest documentation is incomplete: update project docs before advancing.",
        reason="docs_unchanged",
    )

"""Quest and slice machine nodes for the canonical recursive runner."""

from __future__ import annotations

from pathlib import Path
from typing import TYPE_CHECKING

from .. import quest_fs
from ..harness import create_harness
from ..quest_runner import (
    _get_slice_dir,
    git_rev_parse_head,
    perform_role_harness_sequence,
    role_thread_key,
    scaffold_slice_dir,
)
from .quest_v2_predicates import (
    physical_planning_next_state,
    prepare_next_slice_transition,
    quest_documenting_next_state,
    review_physical_plan_next_state,
    slice_implementing_next_state,
    slice_polishing_review_next_state,
)
from ..quest_thread import load_thread, resolve_or_create_thread_spec
from ..quest_types import QuestState, RecursiveSnapshot, SliceState
from .base_node import BaseNode
from .context import RunContext
from .machine import ConcreteStateMachine

if TYPE_CHECKING:
    from .protocols import StateMachine


class PrePlanningGateNode(BaseNode):
    def Execute(self, ctx: RunContext, machine: StateMachine) -> None:
        return None

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        return "PrePlanning"


class CompletedGateNode(BaseNode):
    def Execute(self, ctx: RunContext, machine: StateMachine) -> None:
        return None

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        return "Completed"


class _ThreadLlmNode(BaseNode):
    m_role: str

    def Execute(self, ctx: RunContext, machine: StateMachine) -> None:
        assert ctx.captured_outputs_list is not None
        assert ctx.role_step_seq_box is not None
        if ctx.harness_steps_acc is not None:
            ctx.harness_steps_acc[0] += 1
        quest_dir = ctx.machine_root_dir
        qsi = quest_fs.read_quest_state(quest_dir)
        slice_dir: Path | None = None
        slice_state: SliceState | None = None
        if qsi.state == QuestState.ExecuteSlice and qsi.current_slice is not None:
            slice_dir = _get_slice_dir(quest_dir, qsi.current_slice)
            slice_state = quest_fs.read_slice_state(slice_dir).state
        meta = quest_fs.read_quest_meta(quest_dir)
        profiles = quest_fs.read_execution_config(quest_dir)
        harness_configs = quest_fs.read_harness_configs(quest_dir)
        profile = profiles[self.m_role]
        harness = create_harness(
            profile.harness, harness_configs.get(profile.harness.value)
        )
        quest_rel = quest_dir.resolve().relative_to(ctx.repo_root.resolve()).as_posix()
        slice_rel: str | None = None
        if slice_dir is not None:
            slice_rel = slice_dir.resolve().relative_to(ctx.repo_root.resolve()).as_posix()
        step_base = git_rev_parse_head(ctx.repo_root)
        thread_key = role_thread_key(self.m_role, slice_dir)
        thread_box: list = [
            load_thread(quest_dir, ctx.repo_root, self.m_role, registry_key=thread_key)
        ]
        assert ctx.conductor_repo_path is not None
        assert ctx.quest_docs_dir is not None
        assert ctx.role_step_seq_box is not None
        snum = qsi.current_slice if qsi.state == QuestState.ExecuteSlice else None

        def _create() -> object:
            return resolve_or_create_thread_spec(
                quest_dir,
                ctx.repo_root,
                self.m_role,
                harness,
                meta.quest_number,
                profile.model,
                profile.reasoning_effort,
                profile.idle_timeout_seconds,
                snum,
                registry_key=thread_key,
            )

        perform_role_harness_sequence(
            repo_path=ctx.repo_root,
            quest_dir=quest_dir,
            conductor_repo_path=ctx.conductor_repo_path,
            meta=meta,
            quest_docs_dir=ctx.quest_docs_dir,
            quest_state_info=qsi,
            slice_dir=slice_dir,
            slice_state=slice_state,
            profile=profile,
            harness=harness,
            role_name=self.m_role,
            thread_key=thread_key,
            quest_rel=quest_rel,
            slice_rel=slice_rel,
            step_base_commit=step_base,
            thread_box=thread_box,
            role_step_seq=ctx.role_step_seq_box,
            captured_outputs=ctx.captured_outputs_list,
            create_thread_if_missing=_create,
            event_bus=ctx.event_bus,
            experiment_id=ctx.experiment_id,
        )

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        raise NotImplementedError


class PhysicalPlanningNode(_ThreadLlmNode):
    m_role = "physical_planner"

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        try:
            return physical_planning_next_state(ctx.machine_root_dir)
        except Exception:
            return "PhysicalPlanning"


class ReviewPhysicalPlanNode(_ThreadLlmNode):
    m_role = "physical_plan_reviewer"

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        try:
            return review_physical_plan_next_state(ctx.machine_root_dir)
        except Exception:
            return "ReviewPhysicalPlan"


class PrepareNextSliceNode(BaseNode):
    def __init__(self) -> None:
        self._picked = ""

    def Execute(self, ctx: RunContext, machine: StateMachine) -> None:
        return None

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        nxt, tags = prepare_next_slice_transition(ctx.machine_root_dir)
        self._picked = tags.get("active_slice", "")
        return nxt

    def NodeTags(self, ctx: RunContext, machine: StateMachine) -> dict[str, str]:
        if self._picked:
            return {"active_slice": self._picked}
        return {}


class ExecuteActiveSliceNode(BaseNode):
    m_child_snapshot: object | None

    def __init__(self) -> None:
        self.m_child_snapshot = None

    def Execute(self, ctx: RunContext, machine: StateMachine) -> None:
        quest_dir = ctx.machine_root_dir
        top = quest_fs.read_quest_state(quest_dir)
        active = top.active_slice
        if not active:
            raise RuntimeError("ExecuteActiveSliceNode: missing active_slice")
        slice_dir = quest_dir / "slices" / active
        if not slice_dir.is_dir():
            raise RuntimeError(f"ExecuteActiveSliceNode: missing {slice_dir}")
        child = ctx.state_machine_loader.LoadStateMachine(slice_dir)
        assert isinstance(child, ConcreteStateMachine)
        self.m_child_snapshot = child.RunOneStep(ctx)

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        if self.m_child_snapshot is None:
            raise RuntimeError("child snapshot missing")
        snap: RecursiveSnapshot = self.m_child_snapshot
        if snap.state_after == "Completed":
            return "PrepareNextSlice"
        return "ExecuteSlice"

    def PopChildRecursiveSnapshot(self) -> object | None:
        c = self.m_child_snapshot
        self.m_child_snapshot = None
        return c


class QuestDocumentingNode(_ThreadLlmNode):

"""Protocol definitions for the generic state machine runtime."""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
from typing import Callable, Dict, Mapping, Protocol, Sequence

from ..quest_types import RecursiveSnapshot, RoleProfile, StateMachineId, StateMachineState

NodeFactory = Callable[[], "Node"]


@dataclass
class StateMachineDefinition:
    machine_name: str
    node_map: Dict[str, NodeFactory]
    terminal_states: Sequence[str]


class GitOps(Protocol):
    def IsClean(self, repo_root: Path) -> bool:
        ...

    def GetHeadSha(self, repo_root: Path) -> str:
        ...

    def StageAll(self, repo_root: Path) -> None:
        ...

    def HasStagedChanges(self, repo_root: Path) -> bool:
        ...

    def Commit(self, repo_root: Path, message: str) -> str:
        ...

    def ReadGlobalStep(self, repo_root: Path, state_machine_id: StateMachineId) -> int:
        ...


class ThreadRegistryOps(Protocol):
    def ResolveOrCreateThread(
        self, machine_root_dir: Path, role: str, thread_name: str
    ) -> str:
        ...


class HarnessOps(Protocol):
    def SendThreadMessage(
        self,
        *,
        role: str,
        harness: str,
        model: str,
        thread_id: str,
        prompt: str,
        idle_timeout_seconds: int,
    ) -> str:
        ...


class RoleProfileResolver(Protocol):
    def ResolveRoleProfile(self, state_machine_dir: Path, role: str) -> RoleProfile:
        ...


class StateIo(Protocol):
    def ReadStateMachineState(self, state_machine_dir: Path) -> StateMachineState:
        ...

    def WriteStateMachineState(
        self, state_machine_dir: Path, state: StateMachineState
    ) -> None:
        ...


class Node(Protocol):
    def NodeName(self) -> str:
        ...

    def Execute(self, ctx: RunContext, machine: StateMachine) -> None:
        ...

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        ...

    def NodeTags(self, ctx: RunContext, machine: StateMachine) -> Mapping[str, str]:
        ...

    def PopChildRecursiveSnapshot(self) -> RecursiveSnapshot | None:
        ...


class StateMachine(Protocol):
    def StateMachineDir(self) -> Path:
        ...

    def Definition(self) -> StateMachineDefinition:
        ...

    def ReadState(self) -> StateMachineState:
        ...

    def WriteState(self, new_state: str, tags: Mapping[str, str]) -> None:
        ...

    def RunOneStep(self, ctx: RunContext) -> RecursiveSnapshot:
        ...


class StateMachineLoader(Protocol):
    def LoadStateMachine(self, state_machine_dir: Path) -> StateMachine:
        ...

    def LoadTopStateMachine(self, machine_root_dir: Path) -> StateMachine:
        ...


class StepExecutor(Protocol):
    def ExecuteSingleTopLevelStep(self, ctx: RunContext) -> str:
        ...

class QuestDocumentingNode(_ThreadLlmNode):
    m_role = "documenter"

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        box = ctx.documenter_base_ref_box
        if box is None:
            return "QuestDocumenting"
        ref = box[0]
        if not ref:
            return "QuestDocumenting"
        try:
            return quest_documenting_next_state(
                repo_path=ctx.repo_root,
                quest_dir=ctx.machine_root_dir,
                meta=quest_fs.read_quest_meta(ctx.machine_root_dir),
                documenter_base_ref=ref,
            )
        except Exception:
            return "QuestDocumenting"


class SliceSetupNode(BaseNode):
    def Execute(self, ctx: RunContext, machine: StateMachine) -> None:
        scaffold_slice_dir(machine.StateMachineDir())

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        return "Implementing"


class SliceImplementingNode(_ThreadLlmNode):
    m_role = "implementer"

    def Execute(self, ctx: RunContext, machine: StateMachine) -> None:
        self._step_base = git_rev_parse_head(ctx.repo_root)
        super().Execute(ctx, machine)

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        try:
            return slice_implementing_next_state(machine.StateMachineDir())
        except Exception:
            return "Implementing"


class SlicePolishingReviewNode(_ThreadLlmNode):
    m_role = "polisher_reviewer"

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        try:
            return slice_polishing_review_next_state(machine.StateMachineDir())
        except Exception:
            return "PolishingReview"


class SlicePolishingFixNode(_ThreadLlmNode):
    m_role = "polisher"

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        return "PolishingReview"


class SliceCompletedNode(BaseNode):
    def Execute(self, ctx: RunContext, machine: StateMachine) -> None:
        return None

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        return "Completed"

"""Filesystem, git, and role-profile adapters for the state machine runtime."""

from __future__ import annotations

import subprocess
from pathlib import Path
from typing import Callable

from .. import quest_fs
from ..quest_service import FatalInvariantError
from ..quest_types import RoleProfile, StateMachineId, StateMachineState
from .commit_metadata import (
    CommitMetadataValidationError,
    parse_step_commit_message,
    validate_parsed_step_commit,
)
from .machine import ConcreteStateMachine
from .protocols import StateIo, StateMachineDefinition


def find_quest_root_for_machine_dir(state_machine_dir: Path) -> Path | None:
    """Walk parents until a directory contains both ``meta.json`` and ``state_execution_config.yaml``."""
    cur = state_machine_dir.resolve()
    while True:
        if (cur / "state_execution_config.yaml").is_file() and (cur / "meta.json").is_file():
            return cur
        parent = cur.parent
        if parent == cur:
            return None
        cur = parent


class QuestRootRoleProfileResolver:
